/** The completion script scs generated for the shell, byte-identical to the standalone artifact. */
export function completionScript(shell: CompletionShell): string {
  return COMPLETIONS[shell];
}

function negativeNumber(word: string): boolean {
  return word === "-" || /^-\d/.test(word);
}

export function parse(argv: string[]): ParseResult {
  const values: Record<string, unknown> = {};
  const given: Set<string> = new Set();
  const positionals: string[] = [];
  let command: string | null = null;
  let context: CommandSpec | null = null;
  let posIndex = 0;
  let afterDoubleDash = false;
  let external: string[] | null = null;

  function fields(): FieldSpec[] {
    if (context === null) return SPEC.rootFields;
    return SPEC.rootFields.filter((f) => f.global).concat(context.fields);
  }

  function positionalsOf(): FieldSpec[] {
    return fields().filter((f) => f.positional);
  }

  function label(f: FieldSpec): string {
    if (f.long !== null) return "--" + f.long;
    if (f.short !== null) return "-" + f.short;
    return f.ident;
  }

  function findLong(token: string): FieldSpec | null {
    const name = token.slice(2);
    for (const f of fields()) {
      if (f.positional || f.long === null) continue;
      if (f.long === name || f.longAliases.indexOf(name) !== -1) return f;
    }
    return null;
  }

  function findShort(ch: string): FieldSpec | null {
    for (const f of fields()) {
      if (f.positional) continue;
      if (f.short === ch || f.shortAliases.indexOf(ch) !== -1) return f;
    }
    return null;
  }

  function setFlag(f: FieldSpec): void {
    given.add(f.ident);
    if (f.kind === "count") values[f.ident] = ((values[f.ident] as number | undefined) ?? 0) + 1;
    else values[f.ident] = true;
  }

  function coerce(f: FieldSpec, raw: string): unknown {
    if (f.candidates !== null && f.candidates.indexOf(raw) === -1) {
      throw new UsageError(
        "invalid value '" + raw + "' for " + label(f) + " [possible values: " + f.candidates.join(", ") + "]",
      );
    }
    if (f.typeName === "number") {
      const n = Number(raw);
      if (raw.trim() === "" || Number.isNaN(n)) {
        throw new UsageError("invalid value '" + raw + "' for " + label(f));
      }
      return n;
    }
    return raw;
  }

  function addValue(f: FieldSpec, raw: string): void {
    given.add(f.ident);
    const v = coerce(f, raw);
    if (f.multiple) {
      const arr = (values[f.ident] as unknown[] | undefined) ?? [];
      arr.push(v);
      values[f.ident] = arr;
    } else {
      values[f.ident] = v;
    }
  }

  function takeValue(f: FieldSpec, raw: string): void {
    if (f.delimiter !== null && f.delimiter.length > 0 && raw.indexOf(f.delimiter) !== -1) {
      for (const part of raw.split(f.delimiter)) addValue(f, part);
      return;
    }
    addValue(f, raw);
  }

  function consumeValues(f: FieldSpec, args: string[], start: number): number {
    let i = start;
    let count = 0;
    while (i < args.length) {
      const word = args[i] as string;
      if (f.max !== null && count >= f.max) break;
      if (f.terminator !== null && word === f.terminator) {
        i += 1;
        break;
      }
      if (word === "--") break;
      if (word.length > 1 && word.charAt(0) === "-") {
        if (!(f.allowHyphen || (f.allowNegative && negativeNumber(word)))) break;
      }
      takeValue(f, word);
      count += 1;
      i += 1;
    }
    if (count < f.min) throw new UsageError("a value is required for " + label(f));
    return i;
  }

  function absorb(f: FieldSpec, args: string[], start: number): number {
    const out: string[] = [];
    for (let j = start; j < args.length; j += 1) out.push(args[j] as string);
    for (const word of out) positionals.push(word);
    if (out.length < f.min) throw new UsageError("a value is required for " + label(f));
    if (out.length > 0) given.add(f.ident);
    return args.length;
  }

  function addPositional(f: FieldSpec, word: string): void {
    // A positional value is recorded in positionals by the caller; values
    // holds options only (docs/spec \u00A78.1, \u00A78.3). Coercion still runs, so a
    // positional's candidate/number validation is unchanged.
    given.add(f.ident);
    coerce(f, word);
  }

  let i = 0;
  while (i < argv.length) {
    const word = argv[i] as string;
    if (external !== null) {
      external.push(word);
      i += 1;
      continue;
    }
    if (!afterDoubleDash && word === "--") {
      afterDoubleDash = true;
      i += 1;
      continue;
    }
    if (!afterDoubleDash && word.length > 2 && word.slice(0, 2) === "--") {
      const eq = word.indexOf("=");
      const token = eq === -1 ? word : word.slice(0, eq);
      const inline = eq === -1 ? undefined : word.slice(eq + 1);
      if (token === "--" + SPEC.help.long) throw new HelpRequested(command);
      if (
        SPEC.versionFlag !== null &&
        token === "--" + SPEC.versionFlag.long &&
        (context === null || !SPEC.versionFlag.rootOnly)
      ) {
        throw new VersionRequested();
      }
      const f = findLong(token);
      if (f === null) throw new UsageError("unexpected argument '" + word + "'");
      if (f.kind !== "value") {
        if (inline !== undefined) throw new UsageError("unexpected value '" + inline + "' for " + label(f));
        setFlag(f);
        i += 1;
        continue;
      }
      if (f.requireEquals) {
        if (inline === undefined) {
          throw new UsageError(label(f) + " requires a value, written as " + label(f) + "=VALUE");
        }
        takeValue(f, inline);
        i += 1;
        continue;
      }
      if (inline !== undefined) {
        takeValue(f, inline);
        i += 1;
        continue;
      }
      i = consumeValues(f, argv, i + 1);
      continue;
    }
    if (!afterDoubleDash && word.length >= 2 && word.charAt(0) === "-") {
      const chars = word.slice(1);
      let moved = false;
      for (let k = 0; k < chars.length; k += 1) {
        const ch = chars.charAt(k);
        if (ch === SPEC.help.short) throw new HelpRequested(command);
        if (
          SPEC.versionFlag !== null &&
          ch === SPEC.versionFlag.short &&
          (context === null || !SPEC.versionFlag.rootOnly)
        ) {
          throw new VersionRequested();
        }
        const f = findShort(ch);
        if (f === null) throw new UsageError("unexpected argument '-" + ch + "'");
        if (f.kind !== "value") {
          setFlag(f);
          continue;
        }
        let rest = chars.slice(k + 1);
        if (rest.charAt(0) === "=") rest = rest.slice(1);
        if (rest.length > 0) {
          takeValue(f, rest);
          moved = true;
          break;
        }
        i = consumeValues(f, argv, i + 1);
        moved = true;
        break;
      }
      if (!moved) i += 1;
      continue;
    }
    if (!afterDoubleDash && context === null && SPEC.commands.length > 0) {
      if (word === "help") {
        const next = argv[i + 1] ?? null;
        if (next === null) throw new HelpRequested(null);
        // --all is scs's own spelling for the full body. It is only valid as
        // the final word: help --all x and help --all=x name an argument clap's
        // single-level help does not accept.
        const eq = next.indexOf("=");
        const name = eq === -1 ? next : next.slice(0, eq);
        if (name === "--all") {
          if (next === "--all" && i + 1 === argv.length - 1) throw new HelpRequested(null, true);
          throw new UsageError("unrecognized subcommand '--all'");
        }
        if (COMMANDS.has(next)) throw new HelpRequested(next);
        throw new UsageError("unrecognized subcommand '" + next + "'");
      }
      const found = COMMANDS.get(word);
      if (found !== undefined) {
        context = found;
        command = found.name;
        posIndex = 0;
        i += 1;
        continue;
      }
      if (SPEC.externalSubcommands) {
        external = [word];
        i += 1;
        continue;
      }
      if (positionalsOf().length === 0) {
        throw new UsageError("unrecognized subcommand '" + word + "'");
      }
    }
    const specs = positionalsOf();
    let assigned = false;
    while (posIndex < specs.length) {
      const f = specs[posIndex] as FieldSpec;
      if (f.last && !afterDoubleDash) {
        posIndex += 1;
        continue;
      }
      if (f.trailingVarArg || (f.last && afterDoubleDash)) {
        i = absorb(f, argv, i);
        assigned = true;
        break;
      }
      positionals.push(word);
      addPositional(f, word);
      // A repeatable positional keeps the slot: the next non-option word is
      // absorbed by the same field, so options may interleave. It is legal
      // only as the last positional (SCS210), so there is no later slot to
      // starve. Fixed-arity and last/trailing positionals advance as before.
      if (f.max !== null) posIndex += 1;
      i += 1;
      assigned = true;
      break;
    }
    if (!assigned) throw new UsageError("unexpected argument '" + word + "'");
  }

  if (SPEC.commands.length > 0 && context === null && external === null) {
    throw new UsageError("a subcommand is required");
  }

  for (const f of fields()) {
    if (f.positional || given.has(f.ident)) continue;
    if (f.default !== null) {
      values[f.ident] = f.multiple ? [coerce(f, f.default)] : coerce(f, f.default);
      continue;
    }
    if (f.kind === "flag") {
      values[f.ident] = false;
      continue;
    }
    if (f.kind === "count") {
      values[f.ident] = 0;
      continue;
    }
    if (f.multiple) {
      values[f.ident] = [];
      continue;
    }
    if (f.optional) continue;
    throw new UsageError("the required argument " + label(f) + " was not provided");
  }

  const required = positionalsOf();
  for (let s = 0; s < required.length; s += 1) {
    const f = required[s] as FieldSpec;
    if (f.optional) continue;
    if (s < positionals.length) continue;
    throw new UsageError("the required argument " + label(f) + " was not provided");
  }

  const byIdent: Map<string, FieldSpec> = new Map();
  for (const f of fields()) byIdent.set(f.ident, f);
  for (const f of fields()) {
    if (!given.has(f.ident)) continue;
    for (const c of f.conflicts) {
      if (!given.has(c)) continue;
      const other = byIdent.get(c);
      throw new UsageError(
        "the argument " + label(f) + " cannot be used with " + (other ? label(other) : c),
      );
    }
  }

  return { command, values, positionals, external } as ParseResult;
}
